def f(x, y):                       # сколько программ переводят x в y
    if x == y:
        return 1
    if x > y:
        return 0
    return f(x + 1, y) + f(x * 2, y)

print(f(1, 20), f(1, 10) * f(10, 20))     # всего и через 10

def g(x, y, bad):                  # траектория не содержит bad
    if x > y:
        return 0
    if x == y:
        return 1
    return sum(g(z, y, bad) for z in (x + 1, x * 2) if z != bad)

print(g(1, 20, 8))

def B(x):                          # «Поменяй местами» — или None, если неприменима
    t, o = x // 10 % 10, x % 10
    if t < o:
        return x - 10 * t - o + 10 * o + t
    return None

def f(x, y):
    if x == y:
        return 1
    if x > y:
        return 0
    res = f(x + 1, y)
    b = B(x)
    if b is not None:
        res += f(b, y)
    return res

print(f(100, 141))

def f(x, y):
    if x < y:                     # число только уменьшается
        return 0
    if x == y:
        return 1
    return sum(f(z, y) for z in (x - 3, x - 6, x // 2) if z != 36)

print(f(86, 53) * f(53, 12))       # через 53

def f(x, y):
    if x == y:
        return 1
    if x > y:
        return 0
    s = str(x)
    if '1' in s:                   # команда «замени все 1 на 2» применима, только если в числе есть 1
        return f(x + 1, y) + f(int(s.replace('1', '2')), y)
    return f(x + 1, y)

print(f(11, 92))

def f(x, y):
    if x > y:
        return 0
    if x == y:
        return 1
    return sum(f(z, y) for z in (x + 1, x * 2, x * 3) if z != 11)

print(f(2, 15) * f(15, 25))        # из 2 в 25 через 15, не проходя 11

from functools import lru_cache

@lru_cache(None)
def f(x, y, k):                    # программы ровно из k команд
    if k == 0:
        return int(x == y)
    if x > y:
        return 0
    return f(x + 1, y, k - 1) + f(x * 2, y, k - 1)

print(f(1, 20, 6))

